_F = {
'steam-boiler-supply-erection':[('Is feed water treatment included in a Seamens boiler project?','Yes. Feed water treatment, such as softening, chemical dosing and blow-down control, can be included in the project scope so the new boiler is protected from the first day.')],
'boiler-upgrades-maintenance':[('What does a boiler efficiency audit from Seamens include?','It includes flue gas analysis, a review of stack temperature, blow-down, insulation and condensate losses, and a written list of recommended savings.'),('Can an existing boiler burner be converted to another fuel?','Fuel conversion, for example between gas and oil, is assessed case by case after reviewing the boiler, burner and fuel supply.')],
'captive-power-plant-support':[('Does Seamens support IPPs and co-generation plants?','Yes. Independent power producers, sugar mill co-generation and other captive plants are in scope for water treatment support.'),('Why do deposits form on steam turbine blades?','Silica and dissolved salts carried over with steam deposit on turbine blades, reducing output, which is why steam purity is monitored.')],
'monitoring-controls':[('Can Seamens dosing controllers connect to plant SCADA?','Yes. SCADA-compatible controllers are supplied so water treatment data can be viewed with production data.'),('Which water parameters are monitored online?','Online monitoring typically covers TDS (conductivity) and pH, with automatic blow-down and dosing control.')],
'industrial-air-humidification':[('Why is humidity important in textile mills?','Cotton yarn strength, static and fly depend on air humidity; steady humidity reduces end breaks in spinning and weaving.'),('Which humidification system is best for my mill?','Fogging, ultrasonic or evaporative systems are selected after a site assessment of the hall, machines and water supply.')],
'cooling-tower-supply-erection':[('Does Seamens supply FRP cooling towers?','Yes. FRP counter-flow and induced draft cooling towers are supplied and erected, selected for your duty and site.'),('Can Seamens replace only the fill and nozzles in an old tower?','Yes. Fill media, nozzles and drift eliminators are supplied separately where the tower structure is still sound.')],
'industrial-chiller-systems':[('What chiller capacities does Seamens supply?','Screw chillers from 50 to 2,000 TR, centrifugal chillers for large loads, and both air-cooled and water-cooled options.'),('Does Seamens design cold storage systems?','Yes. Cold storage design, including refrigeration and insulation matched to product and throughput, is in scope.')],
'reverse-osmosis-ro-plants':[('Does Seamens offer Zero Liquid Discharge (ZLD) systems?','Yes. ZLD systems are offered where concentrate discharge is restricted, recovering water and reducing waste.'),('Should I choose a single-pass or double-pass RO plant?','Single pass suits most process and drinking water; double pass is chosen when very low TDS is required, such as high-pressure boiler feed.')],
'erection-commissioning':[('What does turnkey erection and commissioning mean?','One partner manages execution from installation to testing and handover, so the owner deals with a single accountable team.'),('Does Seamens carry out performance testing at handover?','Yes. Performance testing and validation against the design duty are part of commissioning, with results in the handover report.')],
'plant-erection-installation':[('Does Seamens carry out civil and foundation work?','Yes. Civil and structural foundation work is included with mechanical installation where required.'),('Is pipework fabrication included in plant erection?','Yes. Pipework is fabricated, erected, supported and pressure tested as part of the scope.')],
'plant-upgradations':[('Does Seamens carry out energy efficiency upgrades?','Yes. Energy upgrades such as heat recovery, condensate return and efficient drives are assessed and implemented.'),('Can Seamens retrofit automation to an existing line?','Yes. Automation retrofitting is planned around production so existing equipment gains better control.')],
'textile-machinery-parts':[('Which loom types does Seamens supply parts for?','Parts are supplied for rapier, projectile and air-jet looms, as well as spinning frames.'),('Does Seamens supply stenter and dryer parts?','Yes. Stenter and dryer parts are supplied alongside loom and spinning parts.')],
'industrial-spare-parts':[('Which pump spare parts does Seamens supply?','Pump impellers, mechanical seals and bearings are supplied, matched to the pump model and fluid.'),('Does Seamens supply industrial valves and actuators?','Yes. Industrial valves and actuators are supplied for isolation and control duties.')],
'mechanical-maintenance-contracts':[('Do Seamens maintenance contracts include vibration analysis?','Yes. Vibration and thermography analysis are included to detect faults before breakdowns.'),('Is emergency breakdown response included in the contract?','Yes. Contract clients receive priority emergency breakdown response.')],
'custom-fabrication':[('Does Seamens fabricate in stainless steel?','Yes. Both stainless steel and mild steel fabrication are offered, with the material chosen for the duty.'),('Does Seamens supply industrial exhaust fans?','Yes. Industrial belt-drive exhaust fans are supplied with fabricated ductwork and exhaust systems.')],
}
